  "status": "SUPPORTED",
  "claim": {
    "component_id": "C004.component",
    "value": "The reported aggregate does not establish whether the late-start problem is worsening.",
    "scope": "Inference from the 19 late starts among 74 bookings alone.",
    "provenance": {
      "refs": [
        {
          "source_id": "P002",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly denies that the aggregate establishes worsening."
    }
  },
  "signal_basis": {
    "component_id": "C004.signal_basis",
    "value": "An aggregate observation of 19 late starts among 74 bookings, without a temporal breakdown.",
    "scope": "The reported aggregate alone, before considering repeated temporal observations.",
    "provenance": {
      "refs": [
        {
          "source_id": "P002",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span supplies the counts and identifies their aggregate evidential scope."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C004.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No conditional empirical relation is needed for this supported claim."
    }
  },
  "rationale": "The same aggregate can arise from increasing, decreasing or stable late-start rates. Without temporal comparisons, it cannot establish worsening. Observing the mapping's prospective signal would provide additional evidence beyond the claim's explicit aggregate-only scope.",
  "uncertainty": "Whether the problem is actually worsening remains unresolved by the aggregate; this does not undermine the claimed evidential limitation.",
  "anomalies": []
}
